import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    counter = Counter()
    for item in data:
        if isinstance(item, dict):
            counter.update(item.keys())
        else:
            try:
                parsed = __builtins__.__dict__['eval'](item)
                if isinstance(parsed, dict):
                    counter.update(parsed.keys())
            except:
                continue
    return counter
